<script setup lang="ts">
import {onMounted,ref} from 'vue';import {subscriptionsApi,type Subscription} from '@/lib/api';import Button from '@/components/ui/Button.vue';import Input from '@/components/ui/Input.vue';import Dialog from '@/components/ui/Dialog.vue';import Badge from '@/components/ui/Badge.vue';import {useToast} from '@/composables/useToast';const rows=ref<Subscription[]>([]);const open=ref(false);const tmdb=ref('');const {toast}=useToast();async function load(){rows.value=await subscriptionsApi.list()}onMounted(load);async function create(){await subscriptionsApi.create({tmdb_id:Number(tmdb.value)});open.value=false;tmdb.value='';await load();toast('订阅已创建','success')}async function toggle(row:Subscription){await subscriptionsApi.update(row.id,{state:row.state==='active'?'paused':'active'});await load()}async function sync(id:number){const r=await subscriptionsApi.sync(id);toast(r.message,'success')}
</script>
<template><div class="space-y-5"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="text-xl font-semibold">订阅基准</h2><p class="text-sm text-muted">管理订阅状态、同步与画质偏好</p></div><Button @click="open=true">新建订阅</Button></div><div v-if="!rows.length" class="rounded-card border border-border p-6 text-sm text-muted">当前没有订阅。新建订阅需要已存在的媒体 TMDB ID。</div><div class="grid gap-3 md:grid-cols-2 xl:grid-cols-3"><article v-for="row in rows" :key="row.id" class="rounded-card border border-border bg-surface p-4"><div class="flex items-start justify-between"><div><h3 class="font-semibold">{{row.media?.title??`媒体 #${row.media_id}`}}</h3><p class="mt-1 text-xs text-muted">{{row.source}} · #{{row.id}}</p></div><Badge :tone="row.state==='active'?'good':'muted'">{{row.state}}</Badge></div><p class="mt-3 text-xs text-muted">范围：{{JSON.stringify(row.scope)}}</p><div class="mt-3 flex flex-wrap gap-2"><Button variant="outline" size="sm" @click="toggle(row)">{{row.state==='active'?'暂停':'启用'}}</Button><Button variant="outline" size="sm" @click="sync(row.id)">立即同步</Button><Button variant="ghost" size="sm" @click="subscriptionsApi.delete(row.id).then(load)">删除</Button></div></article></div><Dialog :open="open" title="新建订阅" @close="open=false"><form class="space-y-4" @submit.prevent="create"><label class="block space-y-2 text-sm">TMDB 媒体 ID<Input v-model="tmdb" type="number" min="1" required placeholder="例如 12345"/></label><p class="text-xs text-muted">后端仅接受已导入媒体库的 TMDB ID。</p><Button type="submit" class="w-full">创建订阅</Button></form></Dialog></div></template>